`timescale 1ns/1ps
module tb_distortion_core_optimized;
 // 归一化乘法采用两级部分积流水后，可见延迟固定为 15 拍。
 localparam L=15; reg clk=0,rst_n=0,in_valid=0,in_sof=0,in_eol=0; reg [12:0] in_u=0,in_v=0;
 reg signed [31:0] cfg_fx_q19,cfg_fy_q19,cfg_cx_q19,cfg_cy_q19,cfg_inv_fx_q30,cfg_inv_fy_q30,cfg_k1_q28,cfg_k2_q28,cfg_p1_q28,cfg_p2_q28;
 wire signed [63:0] out_src_x_q19,out_src_y_q19; wire signed [31:0] out_x0,out_y0; wire [15:0] out_dx_q16,out_dy_q16; wire out_coord_valid,out_valid,out_sof,out_eol;
 integer err=0,vector_count=0,fd,n,u,v,s,e,id,x,y,x0,y0,dx,dy,ok; reg [8*128-1:0] hdr; always #5 clk=~clk;
 distortion_core_optimized #(.IMAGE_WIDTH(1280),.IMAGE_HEIGHT(720)) dut(.*);
 task cfg(input integer i);begin cfg_fx_q19=471859200;cfg_fy_q19=471859200;cfg_cx_q19=335282176;cfg_cy_q19=188481536;cfg_inv_fx_q30=1193046;cfg_inv_fy_q30=1193046;case(i)0:begin cfg_k1_q28=0;cfg_k2_q28=0;cfg_p1_q28=0;cfg_p2_q28=0;end 1:begin cfg_k1_q28=-67108864;cfg_k2_q28=13421773;cfg_p1_q28=268435;cfg_p2_q28=-268435;end 2:begin cfg_k1_q28=40265318;cfg_k2_q28=5368709;cfg_p1_q28=-268435;cfg_p2_q28=268435;end 3:begin cfg_cx_q19=2146959360;cfg_k1_q28=0;cfg_k2_q28=0;cfg_p1_q28=0;cfg_p2_q28=0;end default:begin cfg_fx_q19=94371840;cfg_fy_q19=94371840;cfg_cx_q19=66846720;cfg_cy_q19=50069504;cfg_inv_fx_q30=5965232;cfg_inv_fy_q30=5965232;cfg_k1_q28=-67108864;cfg_k2_q28=13421773;cfg_p1_q28=268435;cfg_p2_q28=-268435;end endcase end endtask
 task check;begin if(s)cfg(id);@(negedge clk)in_u=u;in_v=v;in_valid=1;in_sof=s;in_eol=e;@(negedge clk)in_valid=0;in_sof=0;in_eol=0;repeat(L-1)@(negedge clk);if(out_valid!==1||out_src_x_q19!==x||out_src_y_q19!==y||out_x0!==x0||out_y0!==y0||out_dx_q16!==dx[15:0]||out_dy_q16!==dy[15:0]||out_coord_valid!==ok||out_sof!==s||out_eol!==e)begin if(err<20)$display("MISMATCH id=%0d u=%0d v=%0d src=(%0d,%0d) expected=(%0d,%0d) split=(%0d,%0d,%0d,%0d,%0d) expected=(%0d,%0d,%0d,%0d,%0d)",id,u,v,out_src_x_q19,out_src_y_q19,x,y,out_x0,out_y0,out_dx_q16,out_dy_q16,out_coord_valid,x0,y0,dx,dy,ok);err=err+1;end @(negedge clk);if(out_valid!==0||out_sof!==0||out_eol!==0||out_coord_valid!==0||out_src_x_q19!==0||out_src_y_q19!==0||out_x0!==0||out_y0!==0||out_dx_q16!==0||out_dy_q16!==0)err=err+1;end endtask
 initial begin cfg(0);repeat(2)@(negedge clk);if(out_valid!==0||out_sof!==0||out_eol!==0||out_coord_valid!==0)err=err+1;rst_n=1;fd=$fopen("vectors/distortion_core_optimized_q18.txt","r");if(!fd)$fatal(1,"vectors missing");n=$fgets(hdr,fd);while(!$feof(fd))begin n=$fscanf(fd,"%d %d %d %d %d %d %d %d %d %d %d %d\n",u,v,s,e,id,x,y,x0,y0,dx,dy,ok);if(n==12)begin vector_count=vector_count+1;check;end end $fclose(fd);if(vector_count==0)$fatal(1,"TEST_FAIL empty optimized-core vector payload");rst_n=0;#1;if(out_valid!==0||out_sof!==0||out_eol!==0||out_coord_valid!==0)err=err+1;if(!err)$display("TEST_PASS: distortion_core_optimized golden_vectors count=%0d",vector_count);else $fatal(1,"TEST_FAIL %0d",err);$finish;end
endmodule
